commands.command:
sudo -n tee /etc/nginx/sites-available/load-backend >/dev/null <<'ANTRIEB_NGINX'
server {
    listen 5660 default_server;
    listen [::]:5660 default_server;
    server_name _;
    location / {
        default_type text/plain;
        return 200 "node1\n";
    }
}
ANTRIEB_NGINX
sudo -n ln -sfn /etc/nginx/sites-available/load-backend /etc/nginx/sites-enabled/load-backend
sudo -n rm -f /etc/nginx/sites-enabled/default
sudo -n nginx -t
sudo -n systemctl enable nginx
sudo -n systemctl restart nginx

